#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>
using namespace std;

const int MAXN=300;
const int MAXM=900000;
int n, t;
int level[MAXN], adj[MAXN], copy_adj[MAXN], fila[MAXN];
int to[MAXM], ant[MAXM], cap[MAXM], pa;
int S, T;
int dx[] = {-1, 0, 1, 0};
int dy[] = {0, 1, 0, -1};
char gr[21][21], gr2[21][21];
int inds[21][21], inds2[21][21], mk[21][21], c[21][21];
int in;
pair<int,int> q[MAXN];
int rp, cp;

void add_edge(int f, int t, int c) {
    to[pa]=t; cap[pa]=c; ant[pa]=adj[f]; adj[f]=pa++;
    to[pa]=f; cap[pa]=0; ant[pa]=adj[t]; adj[t]=pa++;
}

bool valid(int a, int b) {
    return a>=0 && a<n && b>=0 && b<n;
}

void search_bfs(int a, int b) {
    int ini=0, fim=0;
    memset(mk,0,sizeof(mk));
    memset(c,-1,sizeof(c));
    for (int i=0; i<n; i++) for (int j=0; j<n; j++) if (gr[i][j]=='Y') mk[i][j]=1;
    q[fim++]=make_pair(rp,cp);
    q[fim++]=make_pair(a,b);
    c[a][b]=c[rp][cp]=0;
    mk[a][b]=1;
    mk[rp][cp]=2;
    while (ini<fim) {
        auto now=q[ini++];
        int x=now.first, y=now.second;
        if (mk[x][y]==1 && gr2[x][y]>'0' && gr2[x][y]<='9') {
            add_edge(inds[a][b], inds2[x][y], 9);
        }
        if (mk[x][y]==1 && c[x][y]==t) continue;
        for (int i=0; i<4; i++) {
            int nx=x+dx[i], ny=y+dy[i];
            if (valid(nx,ny) && mk[nx][ny]==0) {
                mk[nx][ny]=mk[x][y];
                c[nx][ny]=c[x][y]+1;
                q[fim++]=make_pair(nx,ny);
            } else if (mk[x][y]==1 && valid(nx,ny) && mk[nx][ny]==2 && c[nx][ny]==c[x][y]+1 && gr2[nx][ny]>'0' && gr2[nx][ny]<='9') {
                add_edge(inds[a][b], inds2[nx][ny], 9);
            }
        }
    }
}

int max_flow(int s, int t) {
    int flow=0;
    while (true) {
        if (bfs(s,t)) {
            memcpy(copy_adj, adj, sizeof(adj));
            while (true) {
                int pushed=dfs(s,t,INT_MAX);
                if (pushed) flow+=pushed;
                else break;
            }
        } else break;
    }
    return flow;
}

int main() {
    cin >> n >> t;
    S=202; T=203;
    memset(adj, -1, sizeof(adj));
    pa=0; in=0;
    memset(inds, -1, sizeof(inds));
    memset(inds2, -1, sizeof(inds2));
    for (int i=0; i<n; i++) {
        cin >> gr[i];
        for (int j=0; j<n; j++) {
            if (gr[i][j]>'0' && gr[i][j]<='9') {
                add_edge(S, in, gr[i][j]-'0');
                inds[i][j]=in++;
            }
            if (gr[i][j]=='Z') rp=i, cp=j;
        }
    }
    for (int i=0; i<n; i++) {
        cin >> gr2[i];
        for (int j=0; j<n; j++) {
            if (gr2[i][j]>'0' && gr2[i][j]<='9') {
                add_edge(in, T, gr2[i][j]-'0');
                inds2[i][j]=in++;
            }
        }
    }
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (gr[i][j]>'0' && gr[i][j]<='9' && gr2[i][j]>'0' && gr2[i][j]<='9') add_edge(inds[i][j], inds2[i][j], 9);
            if (gr[i][j]>'0' && gr[i][j]<='9') search_bfs(i,j);
        }
    }
    cout << max_flow(S, T) << "\n";
    return 0;
}
